
local bots={armaak=true,armack=true,armamph=true,armaser=true,armdecom=true,armfark=true,armfast=true,armfboy=true,armfido=true,armhack=true,armmark=true,armmav=true,armsack=true,armscab=true,armsnipe=true,armspid=true,armsptk=true,armspy=true,armvader=true,armzeus=true,armck=true,armflea=true,armham=true,armjeth=true,armpw=true,armrectr=true,armrock=true,armwar=true,corak=true,corck=true,corcrash=true,cornecro=true,corstorm=true,corthud=true,coraak=true,corack=true,coramph=true,corcan=true,cordecom=true,corfast=true,corhack=true,corhrk=true,cormando=true,cormort=true,corpyro=true,corroach=true,corsack=true,corsktl=true,corspec=true,corspy=true,corsumo=true,cortermite=true,corvoyr=true,legaabot=true,legbal=true,legcen=true,leggob=true,legkark=true,leglob=true,legrezbot=true,legadvaabot=true,legajamk=true,legamph=true,legaradk=true,legaspy=true,legbart=true,legdecom=true,leghrk=true,leginc=true,leginfestor=true,legshot=true,legsnapper=true,legsrail=true,legstr=true}local gunships={armkam=true,armbrawl=true,armblade=true,legstronghold=true,legmos=true,corbw=true,corape=true}local vehicles={legamphtank=true,legbar=true,leggat=true,leghades=true,leghelios=true,legmlv=true,legrail=true,legscout=true,legaheattank=true,legamcluster=true,legaskirmtank=true,legavjam=true,legavrad=true,legavroc=true,legfloat=true,leginf=true,legmed=true,legmrv=true,legvcarry=true,legvflak=true,armart=true,armbeaver=true,armcv=true,armfav=true,armflash=true,armjanus=true,armmlv=true,armpincer=true,armsam=true,armstump=true,armacv=true,armbull=true,armconsul=true,armcroc=true,armgremlin=true,armhacv=true,armjam=true,armlatnk=true,armmanni=true,armmart=true,armmerl=true,armsacv=true,armseer=true,armyork=true,corcv=true,corfav=true,corgarp=true,corgator=true,corlevlr=true,cormist=true,cormlv=true,cormuskrat=true,corraid=true,corwolv=true,coracv=true,corban=true,coreter=true,corgol=true,corhacv=true,corintr=true,cormabm=true,cormart=true,corparrow=true,corphantom=true,corprinter=true,correap=true,corsacv=true,corsala=true,corseal=true,corsent=true,corsiegebreaker=true,cortrem=true,corvac=true,corvacct=true,corvrad=true,corvroc=true}local function tolower(s)return s and string.lower(s)or s end for name,ud in pairs(UnitDefs)do if bots[name] then if ud.speed then ud.speed=ud.speed * 1.2 end if ud.maxacc then ud.maxacc=ud.maxacc * 1.2 end if ud.maxdec then ud.maxdec=ud.maxdec * 1.2 end elseif vehicles[name] then if ud.speed then ud.speed=ud.speed * 1.3 end if ud.maxacc then ud.maxacc=ud.maxacc * 1.3 end if ud.maxdec then ud.maxdec=ud.maxdec * 1.3 end elseif gunships[name] then if ud.health then ud.health=ud.health * 1.2 end if ud.nochasecategory and ud.nochasecategory:find("VTOL")then ud.nochasecategory=nil end if ud.weapondefs then for _,w in pairs(ud.weapondefs)do if w.damage and w.damage.default and w.damage.default > 0 then w.damage.vtol=w.damage.default * 1 end if w.range then w.range=w.range * 1.5 end end end if ud.weapons then for _,slot in ipairs(ud.weapons)do if slot.onlytargetcategory and slot.onlytargetcategory:find("SURFACE")then slot.onlytargetcategory=nil end if slot.badtargetcategory and slot.badtargetcategory:find("VTOL")then local nb=slot.badtargetcategory:gsub("VTOL",""):gsub("%s%s+"," "):gsub("^%s+",""):gsub("%s+$","")slot.badtargetcategory=(nb=="")and nil or nb end end end end if ud.canfly then if ud.speed then ud.speed=ud.speed * 2 end if ud.maxacc then ud.maxacc=ud.maxacc * 1.5 end if ud.maxdec then ud.maxdec=ud.maxdec * 1.5 end if ud.verticalspeed then ud.verticalspeed=ud.verticalspeed * 2 end if ud.sightdistance then ud.sightdistance=ud.sightdistance * 2.5 end if ud.airsightdistance then ud.airsightdistance=ud.airsightdistance * 2.5 end if ud.weapondefs then for _,w in pairs(ud.weapondefs)do if w.weaponvelocity then w.weaponvelocity=w.weaponvelocity * 1.5 end end end end if ud.weapondefs then for _,w in pairs(ud.weapondefs)do local wt=tolower(w.weapontype or w.type or "")if wt=="aircraftbomb" then if w.reloadtime then w.reloadtime=w.reloadtime * 0.5 end if w.sprayangle then w.sprayangle=math.floor(w.sprayangle * 0.333 + 0.5)end if w.burst and w.burst > 1 and w.burstrate then w.burstrate=w.burstrate * 0.5 end end end end if name=="armthund" and ud.weapondefs then for _,w in pairs(ud.weapondefs)do if w.range then w.range=w.range * 0.6 end end end if name=="legstronghold" and ud.weapondefs then for _,w in pairs(ud.weapondefs)do if w.reloadtime then w.reloadtime=w.reloadtime * 0.10 end if w.projectiles ~=nil then w.projectiles=3 end if w.range then w.range=800 end if w.name=="Medium Shotgun" then w.damage.default=10 w.damage.vtol=10 end end end end